public class ThickStrokeCrossPainterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String pixel(java.awt.image.BufferedImage img, int x, int y) {
        if (img == null) {
            return "null-image";
        }
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static java.awt.image.BufferedImage render(int width, int height, float thickness) {
        java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(
                width, height, java.awt.image.BufferedImage.TYPE_INT_RGB);
        java.awt.Graphics2D g = img.createGraphics();
        try {
            ThickStrokeCrossPainter.paint(g, width, height, thickness);
        } finally {
            g.dispose();
        }
        return img;
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage a = render(80, 80, 10f);
            java.awt.image.BufferedImage b = render(80, 80, 2f);
            check("thick horizontal band (10,40)", "#000000", pixel(a, 10, 40));
            check("still inside the thick band (10,38)", "#000000", pixel(a, 10, 38));
            check("white well above the band (10,25)", "#FFFFFF", pixel(a, 10, 25));
            check("thick vertical band (40,10)", "#000000", pixel(a, 40, 10));
            check("white left of the vertical band (25,10)", "#FFFFFF", pixel(a, 25, 10));
            check("bands cross at the centre (40,40)", "#000000", pixel(a, 40, 40));
            check("thin stroke still hits the centre line (10,40)", "#000000", pixel(b, 10, 40));
            check("thin stroke leaves (10,36) white", "#FFFFFF", pixel(b, 10, 36));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

